INSERT INTO application_templates (id, legacy_id, title, sections, provenance, created_at, updated_at) VALUES ('tmpl-vern', 'vern', 'Bevaring gjennom aktiv bruk', '{"summary":"[GÅRDSNAVN] er et historisk gårdsmiljø i Rauma som skal bevares gjennom aktiv bruk. Vi søker støtte til [TILTAK] på [BYGG/ANLEGG], med mål om å stanse forfall, ivareta opprinnelig materialbruk og sikre kulturhistoriske kvaliteter for framtiden.","need":"Tiltaket er nødvendig fordi [SKADE/TILSTAND]. Uten gjennomføring er det risiko for [KONSEKVENS].","method":"Arbeidet skal gjennomføres med [MATERIALER/METODE], i tråd med antikvariske prinsipper og faglige anbefalinger fra [RÅDGIVER].","impact":"Prosjektet sikrer kulturmiljøet samtidig som bygningen brukes aktivt til [KULTUR/FRIVILLIGHET/GÅRDSDRIFT]."}', 'legacy_mvp_2026_09_08', '2026-09-20T00:00:00.000Z', '2026-09-20T00:00:00.000Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, sections = excluded.sections, updated_at = excluded.updated_at WHERE application_templates.provenance = 'legacy_mvp_2026_09_08';
INSERT INTO application_templates (id, legacy_id, title, sections, provenance, created_at, updated_at) VALUES ('tmpl-secure', 'secure', 'Akutt sikring', '{"summary":"Vi søker støtte til et avgrenset sikringstiltak på [OBJEKT] etter [STORM/SKADE].","need":"Dagens skade medfører risiko for videre tap av [KONSTRUKSJON/MUR/MATERIALE].","method":"Tiltaket avgrenses til nødvendig stabilisering og sikring: [TILTAK].","impact":"Sikringen kjøper tid og legger grunnlag for senere full restaurering."}', 'legacy_mvp_2026_09_08', '2026-09-20T00:00:00.000Z', '2026-09-20T00:00:00.000Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, sections = excluded.sections, updated_at = excluded.updated_at WHERE application_templates.provenance = 'legacy_mvp_2026_09_08';
INSERT INTO application_templates (id, legacy_id, title, sections, provenance, created_at, updated_at) VALUES ('tmpl-prestudy', 'prestudy', 'Forhåndsundersøkelse', '{"summary":"Vi ønsker en faglig forhåndsundersøkelse av [LÅVE/BYGG] for å etablere et dokumentert grunnlag for restaurering og aktiv bruk.","need":"Vi trenger avklaring av alder, konstruksjon, skadebilde og antikvarisk verdi før større investeringer.","method":"Undersøkelsen skal utføres av [FAGPERSON] og munne ut i tilstandsbeskrivelse, prioriteringer, materialanbefalinger og kostnadsestimat.","impact":"Rapporten skal brukes som beslutningsgrunnlag og vedlegg i senere finansierings- og byggesøknader."}', 'legacy_mvp_2026_09_08', '2026-09-20T00:00:00.000Z', '2026-09-20T00:00:00.000Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, sections = excluded.sections, updated_at = excluded.updated_at WHERE application_templates.provenance = 'legacy_mvp_2026_09_08';
INSERT INTO application_templates (id, legacy_id, title, sections, provenance, created_at, updated_at) VALUES ('tmpl-arena', 'arena', 'ARENA – forprosjekt kulturarena', '{"summary":"Vi vil utvikle en historisk gårdslåve i Rauma til en bærekraftig helårs arena for musikkproduksjon, øving, residencies, konserter og tverrfaglig kultur.","need":"Regionen mangler [BESKRIV BEHOV], samtidig som eksisterende bygningsmasse står foran nødvendig rehabilitering.","method":"Forprosjektet skal avklare arkitektur, akustikk, brann, universell utforming, teknisk infrastruktur, publikumsflyt, brukere, drift og investeringsramme.","impact":"Prosjektet kombinerer gjenbruk av eksisterende bygg med ny kulturinfrastruktur og samarbeid mellom profesjonelle og frivillige aktører."}', 'legacy_mvp_2026_09_08', '2026-09-20T00:00:00.000Z', '2026-09-20T00:00:00.000Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, sections = excluded.sections, updated_at = excluded.updated_at WHERE application_templates.provenance = 'legacy_mvp_2026_09_08';
INSERT INTO application_templates (id, legacy_id, title, sections, provenance, created_at, updated_at) VALUES ('tmpl-venue', 'venue', 'Lokalt kulturbygg', '{"summary":"Prosjektet skal transformere [LÅVEN] fra tidligere landbruksbygg til allment tilgjengelig kulturarena for Rauma og regionen.","need":"Det finnes et dokumentert behov fra [LAG/ARTISTER/BRUKERE].","method":"Tiltaket gjennomføres i faser: [BYGG], [TILGJENGELIGHET], [SCENE/AKUSTIKK], [TEKNIKK].","impact":"Arenaen får en langsiktig driftsmodell gjennom [FORENING] med [BRUKSAVTALE] og årlig aktivitetsplan."}', 'legacy_mvp_2026_09_08', '2026-09-20T00:00:00.000Z', '2026-09-20T00:00:00.000Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, sections = excluded.sections, updated_at = excluded.updated_at WHERE application_templates.provenance = 'legacy_mvp_2026_09_08';
INSERT INTO application_templates (id, legacy_id, title, sections, provenance, created_at, updated_at) VALUES ('tmpl-kulturrom', 'kulturrom', 'Kulturrom – scene/øvingsrom', '{"summary":"Vi søker støtte til å etablere et egnet og varig kulturrom i [LÅVEN] med [AKUSTIKK/LYDISOLASJON/SCENE/UTSTYR].","need":"Dagens rom har [UTFORDRINGER] og kan ikke brukes tilfredsstillende til [AKTIVITET].","method":"Tiltakene bygger på behovsanalyse og tilbud fra [LEVERANDØR/FAGPERSON].","impact":"Investeringen vil gi bedre forhold for [BAND/ARTISTER/ARRANGØRER] og øke antall bruksdøgn fra [X] til [Y]."}', 'legacy_mvp_2026_09_08', '2026-09-20T00:00:00.000Z', '2026-09-20T00:00:00.000Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, sections = excluded.sections, updated_at = excluded.updated_at WHERE application_templates.provenance = 'legacy_mvp_2026_09_08';
INSERT INTO application_templates (id, legacy_id, title, sections, provenance, created_at, updated_at) VALUES ('tmpl-gjenklang', 'gjenklang', 'Gjenklang – fra låve til levende arena', '{"summary":"Vi ønsker å modne en historisk låve til en investeringsklar, flerfunksjonell kulturarena.","need":"Prosjektet er på idé/tidligfase og trenger profesjonell avklaring før byggeinvestering.","method":"Vi vil gjennomføre behovskartlegging, brukerdialog, konseptutvikling, tekniske undersøkelser og økonomisk/driftsmessig modellering.","impact":"Resultatet blir et robust beslutningsgrunnlag for finansiering og gjennomføring."}', 'legacy_mvp_2026_09_08', '2026-09-20T00:00:00.000Z', '2026-09-20T00:00:00.000Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, sections = excluded.sections, updated_at = excluded.updated_at WHERE application_templates.provenance = 'legacy_mvp_2026_09_08';
INSERT INTO application_templates (id, legacy_id, title, sections, provenance, created_at, updated_at) VALUES ('tmpl-event', 'event', 'Arrangement / regionalt kulturfond', '{"summary":"[ARRANGEMENT] skal samle profesjonelle utøvere, frivillige og publikum på [GÅRDSNAVN] i Rauma.","need":"Prosjektet møter behovet for [KULTURTILBUD/MØTEPLASS/KOMPETANSE].","method":"Programmet består av [KONSERTER/WORKSHOPS/JAMS] med profesjonelle aktører honorert etter relevante bransjestandarder.","impact":"Tiltaket skaper aktivitet, nettverk og lokal/regional verdiskaping og dokumenteres gjennom publikumstall, deltakelse og evaluering."}', 'legacy_mvp_2026_09_08', '2026-09-20T00:00:00.000Z', '2026-09-20T00:00:00.000Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, sections = excluded.sections, updated_at = excluded.updated_at WHERE application_templates.provenance = 'legacy_mvp_2026_09_08';
